// Send sensor readings as JSON — easy to parse on PC
// Format: {"t":1234,"temp":23.4,"hum":55.1,"light":789}

#include <DHT.h>
DHT dht(4, DHT22);

void setup() {
  Serial.begin(115200);
  dht.begin();
}

void loop() {
  float temp = dht.readTemperature();
  float hum  = dht.readHumidity();
  int   light = analogRead(A0);

  if (!isnan(temp) && !isnan(hum)) {
    Serial.print(F("{\"t\":"));
    Serial.print(millis() / 1000);
    Serial.print(F(",\"temp\":"));
    Serial.print(temp, 1);
    Serial.print(F(",\"hum\":"));
    Serial.print(hum, 1);
    Serial.print(F(",\"light\":"));
    Serial.print(light);
    Serial.println(F("}"));
  }
  delay(2000);
}

const int LED_PIN = 13;
String inputBuffer = "";

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);
  Serial.println(F("Commands: LED_ON, LED_OFF, STATUS"));
}

void handleCommand(const String& cmd) {
  if (cmd == "LED_ON") {
    digitalWrite(LED_PIN, HIGH);
    Serial.println(F("OK: LED on"));
  } else if (cmd == "LED_OFF") {
    digitalWrite(LED_PIN, LOW);
    Serial.println(F("OK: LED off"));
  } else if (cmd == "STATUS") {
    Serial.print(F("Uptime: "));
    Serial.print(millis() / 1000);
    Serial.print(F("s  A0: "));
    Serial.println(analogRead(A0));
  } else {
    Serial.print(F("ERR: Unknown command: "));
    Serial.println(cmd);
  }
}

void loop() {
  // Read incoming serial data character by character
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') {
      inputBuffer.trim();
      if (inputBuffer.length() > 0) {
        handleCommand(inputBuffer);
        inputBuffer = "";
      }
    } else {
      inputBuffer += c;
      if (inputBuffer.length() > 32) inputBuffer = "";  // overflow guard
    }
  }
}

#include <SoftwareSerial.h>
// SoftwareSerial(RX_pin, TX_pin)
// Connect HC-05 Bluetooth TX → Arduino pin 10
// Connect HC-05 Bluetooth RX → Arduino pin 11
SoftwareSerial bluetooth(10, 11);

void setup() {
  Serial.begin(115200);    // USB debug
  bluetooth.begin(9600);   // HC-05 default baud
  Serial.println(F("Bluetooth ready"));
  bluetooth.println(F("AT"));  // test HC-05 with AT command
}

void loop() {
  // Bridge: forward bluetooth → USB serial
  if (bluetooth.available()) {
    Serial.write(bluetooth.read());
  }
  // Bridge: forward USB serial → bluetooth
  if (Serial.available()) {
    bluetooth.write(Serial.read());
  }
}
